import Microsoft.Office.Interop.Excel;

class ExcelTable {
    let workbook: Workbook
    let worksheet: Worksheet

    init(workbook: Workbook, worksheet: Worksheet) {
        self.workbook = workbook
        self.worksheet = worksheet
    }

    func addRow(row: [String]) {
        let rowRange = worksheet.Cells.CreateRange("A1", "H1")
        rowRange.Value = row
    }

