function tense = identify_tense(sentence)
    % Split the sentence into words
    words = strsplit(sentence, ' ');

    % Identify the verb
    verb = words(end);

    % Check for present tense
    if verb == 'be' || verb == 'have' || verb == 'do' || verb == 'does' || verb == 'did'
        tense = 'present';
    elseif verb == 'will' || verb == 'would' || verb == 'should' || verb == 'could'
        tense = 'future';
    elseif verb == 'has' || verb == 'had' || verb == 'is' || verb == 'are' || verb == 'was' || verb == 'were'
        tense = 'past';
    elseif verb == 'been' || verb == 'done' || verb == 'gone' || verb == 'come' || verb == 'come'
        tense = 'perfect';
    elseif verb == 'being' || verb == 'happening' || verb == 'going' || verb == 'coming'
        tense = 'progressive';
    else
        tense = 'other';
    end
end

