Here's a simple example of a generic REST service wrapper class in C# with auth token handling:

```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class RestServiceWrapper<T>
{
    private readonly string _baseUrl;
    private readonly string _authToken;

    public RestServiceWrapper(string baseUrl, string authToken)
    {
        _baseUrl = baseUrl;
        _authToken = authToken;
    }

    public async Task<T> GetAsync()
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);

            var response = await client.GetAsync($"{_baseUrl}/api/data");
            response.EnsureSuccessStatusCode();

            return JsonConvert.DeserializeObject<T>(await response.Content.ReadAsStringAsync());
        }
    }
}

public class Data
{
    public string Property1 { get; set; }
    public int Property2 { get; set; }
}

public class Program
{
    public static void Main(string[] args)
    {
        var baseUrl = "https://example.com/api";
        var authToken = "your-auth-token-here";

        var restServiceWrapper = new RestServiceWrapper<Data>(baseUrl, authToken);
        var data = await restServiceWrapper.GetAsync();

        Console.WriteLine(data.Property1);
        Console.WriteLine(data.Property2);
    }
}
```

In this example, we have a `RestServiceWrapper` class that takes a base URL and an auth token as constructor parameters. The `GetAsync` method makes a GET request to the specified endpoint, including the auth token in the authorization header. The method returns the response as a `Task<T>`, where `T` is the type of the data being returned by the API.

