Here's a simple Google Apps Script that searches for a place name in a column and stores the latitude and longitude in other columns:

```javascript
function searchPlace() {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  var dataRange = sheet.getRange("A2:A"); // Assuming your data starts in cell A2
  var placeName = dataRange.getValue();

  var geocoder = new google.maps.Geocoder();
  geocoder.geocode({ 'address': placeName }, function(results, status) {
    if (status == 'OK') {
      var latitude = results[0].geometry.location.lat();
      var longitude = results[0].geometry.location.lng();

      sheet.getRange("B2").setValue(latitude); // Assuming you want to store the latitude in column B
      sheet.getRange("C2").setValue(longitude); // Assuming you want to store the longitude in column C
    } else {
      sheet.getRange("B2").setValue(""); // Assuming you want to clear the latitude value if the search fails
      sheet.getRange("C2").setValue(""); // Assuming you want to clear the longitude value if the search fails
    }
  });
}
```

