Here's a Go program that parses a struct in a Go source file and generates an Avro schema from it. The program takes the name of the Go source file and the name of the struct as input, and outputs a file named `struct.avsc`.

```go
package main

import (
	"fmt"
	"io/ioutil"
	"log"
	"regexp"
	"strings"

	"github.com/apache/avro/avro"
)

func main() {
	if len(argv) != 3 {
		log.Fatal("Usage: ./parse_go_struct <go_source_file> <struct_name>")
	}

	goSourceFile := argv[1]
	structName := argv[2]

	content, err := ioutil.ReadFile(goSourceFile)
	if err != nil {
		log.Fatal(err)
	}

	// Extract the struct definition from the Go source file
	re := regexp.MustCompile(`type (?P<struct_name>\w+) struct {`)
	matches := re.FindStringSubmatch(string(content))
	if len(matches) != 2 {
		log.Fatal("Unable to find struct definition in the Go source file")
	}

	structDef := matches[1]

	// Generate the Avro schema from the struct definition
	schema, err := avro.ParseSchema(structDef)
	if err != nil {
		log.Fatal(err)
	}

	// Write the Avro schema to a file
	err = ioutil.WriteFile("struct.avsc", []byte(schema), 0644)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Printf("Avro schema generated for %s struct\n", structName)
}
```

To use this program, save it as a `.go` file (e.g., `parse_go_struct.go`) and run it with the name of the Go source file and the name of the struct as arguments:

```
./parse_go_

