Here's a C# program that summarizes the key points of the article on climate change:

```csharp
using System;
using System.IO;
using System.Text;

class ClimateChangeSummary
{
    static void Main(string[] args)
    {
        string filePath = "article.txt";
        if (!File.Exists(filePath))
        {
            Console.WriteLine("Error: File not found.");
            return;
        }

        string content = File.ReadAllText(filePath);
        string summary = ExtractSummary(content);
        Console.WriteLine(summary);
    }

    static string ExtractSummary(string content)
    {
        // Keywords to search for
        string[] keywords = { "climate change", "global warming", "ocean levels", "global temperatures", "species loss", "human activities" };

        // Regular expression pattern to match keywords
        string pattern = string.Join("|", keywords) + "\\b";

        // Match keywords in the content
        MatchCollection matches = Regex.Matches(content, pattern);

        // Create summary based on matched keywords
        StringBuilder summary = new StringBuilder();
        foreach (Match match in matches)
        {
            summary.AppendLine(match.Value);
        }

        // Return summary
        return summary.ToString();
    }
}
```

This program reads the contents of an article file (in this case, "article.txt") and extracts the keywords related to climate change. It then creates a summary based on these keywords. You can modify the keywords list and the regular expression pattern to suit your needs.

