Here's a simple React utility to remove widows. This utility will check if the text inside an element is wider than its container and adjust the font size to fit the content without creating a widow.

```javascript
import React, { useState } from 'react';

const RemoveWidows = ({ children }) => {
  const [fontSize, setFontSize] = useState(16);

  const handleResize = () => {
    const containerWidth = document.querySelector('.container').offsetWidth;
    const textWidth = document.querySelector('.text').offsetWidth;

    if (textWidth > containerWidth) {
      setFontSize((prevFontSize) => prevFontSize - 2);
    } else {
      setFontSize((prevFontSize) => prevFontSize + 2);
    }
  };

  return (
    <div className="container">
      <div className="text" style={{ fontSize }}>{children}</div>
    </div>
  );
};

export default RemoveWidows;
```

To use this utility, simply wrap your content with the `RemoveWidows` component:

```javascript
