```javascript
const { Redis } = require('ioredis');

class RedisClient {
  constructor() {
    this.client = new Redis({
      host: 'localhost',
      port: 6379,
      db: 0,
    });

    this.client.on('error', (err) => {
      console.error(`Redis error: ${err}`);
    });
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (err) {
      return false;
    }
  }

  async get(key) {
    const value = await this.client.get(key);
    return value;
  }

  async set(key, value, duration) {
    await this.client.setex(key, duration, value);
  }

  async del(key) {
    await this.client.del(key);
  }
}

const redisClient = new RedisClient();

module.exports = { redisClient };
```

This code defines the `RedisClient` class with a constructor that sets up the Redis connection, and four methods for interacting with Redis: `isAlive`, `get`, `set`, and `del`. The `redisClient` instance is created and exported at the bottom of the file.

