To identify if a given sentence in Go contains a double negative, you can follow these steps:

1. Define a slice of specific negative words.
2. Split the sentence into individual words.
3. Iterate through each word in the sentence.
4. Check if the word is in the slice of negative words.
5. Check if the word is followed by the phrase "not".
6. If both conditions are satisfied, print a message indicating that the sentence contains a double negative.

Here's the Go code to implement this approach:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"not", "never", "no", "none", "nothing"}
	sentence := "He isn't not worried about the coronavirus situation"

	words := strings.Split(sentence, " ")
	for _, word := range words {
		if containsNegativeWord(word, negativeWords) && hasNotFollowing(word, negativeWords) {
			fmt.Println("The sentence contains a double negative.")
			break
		}
	}
}

func containsNegativeWord(word string, negativeWords []string) bool {
	for _, negWord := range negativeWords {
		if word == negWord {
			return true
		}
	}
	return false
}

func hasNotFollowing(word string, negativeWords []string) bool {
	if len(word) > 1 && word[len(word)-1] == 't' && word[len(word)-2] == 'o' {
		return true
	}
	return false
}
```

