# Function to check if an SID is present in the SIDHistory of a user or group
function CheckSIDInSIDHistory($sid) {
    $adUsers = Get-ADUser -Filter {SID -eq $sid} -Properties SIDHistory
    return ($adUsers -ne $null)
}

# Function to recursively check folders for ACLs with SIDs in the SIDHistory
function CheckFoldersForACLS($path) {
    Get-ChildItem -Path $path -Directory | ForEach-Object {
        $acl = Get-Acl -Path $_.FullName
        foreach ($access in $acl.Access) {
            if ($access.IdentityReference -match '^S-1-5-21-(?<sid>\d+)$') {
                $sid = $matches['sid']
                if (CheckSIDInSIDHistory($sid)) {
                    Write-Host "Found ACL with SID in SIDHistory: $_"
                }
            }
        }
        CheckFoldersForACLS($_.FullName)
    }
}

# Start the search from the specified folder
CheckFoldersForACLS($startPath)
```

Replace `C:\Your_Start_Folder` with the folder path you want to start the search from. This script will recursively check all folders under the specified path for ACLs with SIDs in the SIDHistory of users or groups in the domain.
